{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Urapidil, a methoxyphenyl/piperazine drug, has a human absolute oral bioavailability of 78%, directly supporting high F for the query's methoxy-substituted heteroaromatic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Atazanavir, which contains a pyridine and multiple polar groups, has oral bioavailability >90% with food, supporting high F for the query's pyridyl-containing core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "GSK1322322, a methoxy- and pyrimidine-containing drug with basic amine groups, has absolute F of 77% after a meal, supporting high F for the query's aminopyrimidine/piperidine system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bosentan, a pyrimidine sulfonamide with methoxyaryl groups, has absolute F of 50% in healthy subjects, supporting high F for the query's sulfonamide/methoxy/pyrimidine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Sildenafil, a pyrimidine-type sulfonamide with methoxy and basic amine groups, has absolute F of 41%, supporting high F for the query's similar polar heteroaromatic sulfonamide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Acalabrutinib, an aminopyrimidine with a pyridine substituent, has absolute F of 25.3%, still above the 20% threshold and supporting high F for the query's aminopyrimidine/pyridine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib fed-state absolute F was 13.9%, the only sub-20% value among high-transfer analogues, but its carboxylic acid/stilbene structure and food-dependent absorption are not shared by the query; fasting F was 35%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability measurements for structurally related heteroaromatic drugs containing methoxy, pyrimidine, sulfonamide, and pyridine motifs consistently exceed 20%, supporting a high oral bioavailability prediction for the query. The only sub-20% record is a fed-state rigosertib value with structural features not shared by the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Food effects on absorption are unknown for the query.",
    "First-pass metabolism and transporter-mediated efflux liabilities have not been directly assessed.",
    "Solubility-limited absorption cannot be fully excluded without experimental data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

